import os
import importlib.util

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
format_phone = target.format_phone


def test_format_phone_standard():
    """Test that 10 digits are formatted as (XXX) XXX-XXXX per spec."""
    result = format_phone("1234567890")
    # Per docstring: format should be (XXX) XXX-XXXX
    assert result == "(123) 456-7890", f"Expected '(123) 456-7890', got '{result}'"


def test_format_phone_various_numbers():
    """Test various valid 10-digit numbers."""
    assert format_phone("5551234567") == "(555) 123-4567"
    assert format_phone("8005551234") == "(800) 555-1234"


def test_format_phone_rejects_non_string():
    """Test that non-string input raises TypeError."""
    try:
        format_phone(1234567890)
        assert False, "Should have raised TypeError"
    except TypeError:
        pass


def test_format_phone_rejects_too_few_digits():
    """Test that fewer than 10 digits raises ValueError."""
    try:
        format_phone("123456789")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_format_phone_rejects_too_many_digits():
    """Test that more than 10 digits raises ValueError."""
    try:
        format_phone("12345678901")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_format_phone_rejects_separators():
    """Test that separators raise ValueError per spec."""
    try:
        format_phone("123-456-7890")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_format_phone_rejects_spaces():
    """Test that spaces raise ValueError per spec."""
    try:
        format_phone("123 456 7890")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_format_phone_rejects_country_code():
    """Test that country codes raise ValueError per spec."""
    try:
        format_phone("11234567890")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_format_phone_rejects_non_digits():
    """Test that non-digit characters raise ValueError."""
    try:
        format_phone("123456789a")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_format_phone_empty_string():
    """Test that empty string raises ValueError."""
    try:
        format_phone("")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass

