import importlib.util

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
sorted_intersection = target.sorted_intersection


def test_basic_intersection():
    result = sorted_intersection([1, 2, 3], [2, 3, 4])
    assert result == [2, 3], f"Expected [2, 3], got {result}"


def test_duplicates_in_left():
    """Each shared integer should appear once even if duplicated in inputs."""
    result = sorted_intersection([1, 1, 2], [1, 2, 3])
    assert result == [1, 2], f"Expected [1, 2], got {result}"


def test_duplicates_in_right():
    result = sorted_intersection([1, 2, 3], [2, 2, 3, 3])
    assert result == [2, 3], f"Expected [2, 3], got {result}"


def test_duplicates_in_both():
    result = sorted_intersection([1, 1, 2, 2], [1, 1, 2, 2])
    assert result == [1, 2], f"Expected [1, 2], got {result}"


def test_empty_intersection():
    result = sorted_intersection([1, 2], [3, 4])
    assert result == [], f"Expected [], got {result}"


def test_empty_inputs():
    assert sorted_intersection([], [1, 2]) == []
    assert sorted_intersection([1, 2], []) == []


def test_sorted_output():
    """Output should be sorted ascending."""
    result = sorted_intersection([5, 3, 1], [1, 5, 9])
    assert result == [1, 5], f"Expected [1, 5], got {result}"


def test_single_common_element():
    result = sorted_intersection([1, 2, 3], [3])
    assert result == [3], f"Expected [3], got {result}"


def test_rejects_non_list():
    try:
        sorted_intersection("not a list", [1, 2])
        assert False, "Should have raised TypeError"
    except TypeError:
        pass


def test_rejects_non_int_in_list():
    try:
        sorted_intersection([1, "two", 3], [1, 2, 3])
        assert False, "Should have raised TypeError"
    except TypeError:
        pass


def test_all_elements_common():
    result = sorted_intersection([1, 2, 3], [1, 2, 3])
    assert result == [1, 2, 3], f"Expected [1, 2, 3], got {result}"


def test_negative_numbers():
    result = sorted_intersection([-1, 0, 1], [-1, 1, 2])
    assert result == [-1, 1], f"Expected [-1, 1], got {result}"
"}

